-- Reproducible seed: 30 road-code or COLREG questions per vehicle.
-- Land vehicles use the current Italian Highway Code; naval units use IMO COLREG 1972.
with land_questions as (
 select * from jsonb_to_recordset($land$[{"prompt":"A cosa deve essere commisurata la distanza di sicurezza?","options":["Alla velocità, alle condizioni del traffico e alle condizioni della strada","Alla distanza dal margine destro","Alla cilindrata del veicolo","Soltanto alla lunghezza del veicolo"],"correct_index":0,"explanation":"Art. 149 CdS — distanza di sicurezza. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 149 CdS — distanza di sicurezza"},{"prompt":"Che cosa deve fare il conducente se il veicolo presenta un guasto che compromette la sicurezza?","options":["Continuare fino al termine del turno","Disattivare le spie","Non proseguire la marcia nelle condizioni di pericolo e adottare le misure previste","Aumentare la velocità per ridurre il tempo di esposizione"],"correct_index":2,"explanation":"Art. 79 CdS — efficienza dei veicoli. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 79 CdS — efficienza dei veicoli"},{"prompt":"Che cosa disciplina l’art. 187?","options":["La sosta in doppia fila","L’uso delle cinture","La guida dopo aver assunto sostanze stupefacenti o psicotrope nei termini previsti dalla norma","Il trasporto di merci pericolose"],"correct_index":2,"explanation":"Art. 187 CdS — guida dopo assunzione di sostanze. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 187 CdS — guida dopo assunzione di sostanze"},{"prompt":"Che cosa impone l’art. 186 in materia di alcol?","options":["Si applica soltanto ai conducenti professionali","Vieta la guida in stato di ebbrezza e disciplina le relative soglie e sanzioni","Consente sempre la guida dopo una bevanda","Riguarda soltanto i veicoli pesanti"],"correct_index":1,"explanation":"Art. 186 CdS — guida in stato di ebbrezza. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 186 CdS — guida in stato di ebbrezza"},{"prompt":"Che cosa prescrive l’art. 146?","options":["I segnali di divieto sono facoltativi per i veicoli di servizio","Gli utenti devono rispettare la segnaletica stradale e le prescrizioni indicate","I segnali verticali valgono solo per i mezzi pesanti","La segnaletica vale solo in assenza di agenti"],"correct_index":1,"explanation":"Art. 146 CdS — inosservanza della segnaletica. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 146 CdS — inosservanza della segnaletica"},{"prompt":"Chi deve utilizzare le cinture di sicurezza nei veicoli per i quali sono previste?","options":["Soltanto il conducente","Soltanto fuori dai centri abitati","Conducente e passeggeri, secondo le disposizioni dell’art. 172","Solo i passeggeri anteriori"],"correct_index":2,"explanation":"Art. 172 CdS — cinture di sicurezza. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 172 CdS — cinture di sicurezza"},{"prompt":"Come devono essere rispettate le segnalazioni impartite dagli agenti del traffico?","options":["Prevalgono sulle altre segnalazioni secondo l’art. 43","Valgono soltanto fuori dai centri abitati","Solo se coincidono con il semaforo","Sono facoltative se la strada è libera"],"correct_index":0,"explanation":"Art. 43 CdS — segnalazioni degli agenti. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 43 CdS — segnalazioni degli agenti"},{"prompt":"Dove è vietata la fermata o la sosta in prossimità di un attraversamento pedonale?","options":["Soltanto di notte","Nei casi e alle distanze stabilite dall’art. 158","Solo sulle autostrade","Solo se il marciapiede è stretto"],"correct_index":1,"explanation":"Art. 158 CdS — divieti di fermata e sosta. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 158 CdS — divieti di fermata e sosta"},{"prompt":"Durante la marcia, quale condotta è vietata dall’art. 173?","options":["Usare apparecchi che comportano allontanamento delle mani dal volante o distrazione non consentita","Utilizzare i comandi integrati ammessi","Regolare il climatizzatore prima della partenza","Ascoltare la radio a volume moderato"],"correct_index":0,"explanation":"Art. 173 CdS — uso di dispositivi durante la guida. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 173 CdS — uso di dispositivi durante la guida"},{"prompt":"In assenza di diversa segnalazione, quale regola generale disciplina la precedenza agli incroci?","options":["Ha sempre precedenza il veicolo più grande","Ha precedenza chi arriva per primo a prescindere dalla posizione","Ha precedenza chi procede più velocemente","Si dà precedenza a chi proviene da destra"],"correct_index":3,"explanation":"Art. 145 CdS — precedenza. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 145 CdS — precedenza"},{"prompt":"In caso di incidente con danno alle persone, quale obbligo fondamentale ha il conducente coinvolto?","options":["Spostare sempre i feriti prima di avvisare i soccorsi","Fermarsi e prestare l’assistenza richiesta dalla legge","Allontanarsi se il veicolo è marciante","Limitarsi a fotografare la scena"],"correct_index":1,"explanation":"Art. 189 CdS — comportamento in caso di incidente. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 189 CdS — comportamento in caso di incidente"},{"prompt":"In caso di incidente con soli danni alle cose, i conducenti devono comunque:","options":["Ripartire senza scambiarsi dati","Lasciare i veicoli nella carreggiata in ogni circostanza","Fermarsi e fornire le generalità e le informazioni necessarie nei termini di legge","Attendere sempre un’ambulanza"],"correct_index":2,"explanation":"Art. 189 CdS — obblighi dopo incidente. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 189 CdS — obblighi dopo incidente"},{"prompt":"In presenza del segnale di STOP, il conducente deve:","options":["Fermarsi solo quando arriva un mezzo da destra","Arrestarsi e dare precedenza secondo la segnalazione","Rallentare soltanto se vede altri veicoli","Proseguire se non sente clacson"],"correct_index":1,"explanation":"Art. 145 CdS — arresto all’intersezione. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 145 CdS — arresto all’intersezione"},{"prompt":"Prima di cambiare corsia o direzione, il conducente deve:","options":["Azionare il clacson e spostarsi","Frenare bruscamente","Fidarsi esclusivamente degli specchi","Assicurarsi che la manovra sia sicura e segnalarla con anticipo"],"correct_index":3,"explanation":"Art. 154 CdS — cambiamento di direzione e corsia. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 154 CdS — cambiamento di direzione e corsia"},{"prompt":"Qual è il comportamento corretto prima di aprire una portiera verso la carreggiata?","options":["Aprirla senza controllare se si è fermi","Aprirla solo con il motore acceso","Aprirla rapidamente per segnalare la presenza","Verificare che non si crei pericolo o intralcio agli altri utenti"],"correct_index":3,"explanation":"Art. 157 CdS — arresto, fermata e apertura delle porte. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 157 CdS — arresto, fermata e apertura delle porte"},{"prompt":"Qual è il criterio generale per scegliere la velocità secondo l’art. 141?","options":["Mantenere sempre il limite massimo indicato","Usare la velocità massima del mezzo","Adeguarla alle condizioni della strada, del traffico e della visibilità","Seguire soltanto la velocità del veicolo che precede"],"correct_index":2,"explanation":"Art. 141 CdS — velocità adeguata alle condizioni. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 141 CdS — velocità adeguata alle condizioni"},{"prompt":"Qual è il limite massimo generale nei centri abitati, salvo diversa segnalazione?","options":["70 km/h","50 km/h","30 km/h","90 km/h"],"correct_index":1,"explanation":"Art. 142 CdS — centri abitati. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 142 CdS — centri abitati"},{"prompt":"Qual è il limite massimo generale sulle autostrade, salvo diversa segnalazione o disciplina?","options":["130 km/h","90 km/h","110 km/h","150 km/h in ogni autostrada"],"correct_index":0,"explanation":"Art. 142 CdS — limiti massimi generali. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 142 CdS — limiti massimi generali"},{"prompt":"Qual è il limite massimo generale sulle strade extraurbane principali?","options":["130 km/h","70 km/h","90 km/h","110 km/h"],"correct_index":3,"explanation":"Art. 142 CdS — strade extraurbane principali. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 142 CdS — strade extraurbane principali"},{"prompt":"Qual è l’obbligo generale relativo alla copertura assicurativa dei veicoli a motore?","options":["Serve soltanto fuori dall’Italia","È richiesta solo ai veicoli commerciali","È facoltativa se il veicolo è usato raramente","Il veicolo deve essere coperto dall’assicurazione obbligatoria nei casi previsti"],"correct_index":3,"explanation":"Art. 193 CdS — obbligo di assicurazione. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 193 CdS — obbligo di assicurazione"},{"prompt":"Qual è la condotta corretta se un agente impartisce un segnale manuale in contrasto con il semaforo?","options":["Attenersi al segnale dell’agente che regola il traffico","Seguire il veicolo davanti","Seguire il semaforo perché è automatico","Fermarsi e attendere che il semaforo cambi"],"correct_index":0,"explanation":"Art. 43 CdS — prevalenza delle segnalazioni degli agenti. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 43 CdS — prevalenza delle segnalazioni degli agenti"},{"prompt":"Qual è la regola generale sull’uso dei proiettori abbaglianti quando si incrociano altri veicoli?","options":["Devono essere sostituiti con i proiettori anabbaglianti quando previsto per non abbagliare","Possono essere usati per imporre la precedenza","Devono restare sempre accesi","Sono obbligatori nei centri abitati"],"correct_index":0,"explanation":"Art. 153 CdS — uso dei dispositivi di illuminazione. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 153 CdS — uso dei dispositivi di illuminazione"},{"prompt":"Quale condotta è vietata in autostrada dall’art. 176?","options":["Invertire il senso di marcia o effettuare retromarcia sulla carreggiata, salvo eccezioni tassative","Rallentare per traffico intenso","Usare le corsie di marcia secondo la segnaletica","Mantenere la distanza di sicurezza"],"correct_index":0,"explanation":"Art. 176 CdS — comportamento in autostrada. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 176 CdS — comportamento in autostrada"},{"prompt":"Quale obbligo riguarda la massa e la sistemazione del carico?","options":["Il carico deve essere sistemato senza alcun vincolo","Il carico può occultare le luci posteriori","Il carico può superare la massa ammessa se ben fissato","Il carico non deve compromettere stabilità e sicurezza e deve rispettare i limiti prescritti"],"correct_index":3,"explanation":"Artt. 164 e 167 CdS — sistemazione e limiti del carico. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Artt. 164 e 167 CdS — sistemazione e limiti del carico"},{"prompt":"Quale regola generale tutela i pedoni sugli attraversamenti?","options":["Il pedone deve attendere che non vi siano veicoli in tutta la strada","Il conducente deve moderare la velocità e fermarsi per consentire l’attraversamento nei casi previsti","Il conducente ha sempre precedenza se procede diritto","La precedenza dipende dalla cilindrata"],"correct_index":1,"explanation":"Art. 191 CdS — comportamento verso i pedoni. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 191 CdS — comportamento verso i pedoni"},{"prompt":"Quale regola si applica ai documenti di circolazione e guida richiesti?","options":["Devono essere disponibili secondo le modalità e gli obblighi previsti dall’art. 180","Sono sostituiti dal tesserino di servizio","Non è necessario averli se il conducente conosce la targa","Sono richiesti solo ai veicoli immatricolati all’estero"],"correct_index":0,"explanation":"Art. 180 CdS — possesso dei documenti. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 180 CdS — possesso dei documenti"},{"prompt":"Quando è consentito effettuare un sorpasso?","options":["Sempre se il veicolo che precede è lento","Quando si supera il limite per poco tempo","Quando la manovra può compiersi senza pericolo o intralcio e nel rispetto delle regole","Anche senza visibilità se si usa il lampeggiante"],"correct_index":2,"explanation":"Art. 148 CdS — sorpasso. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 148 CdS — sorpasso"},{"prompt":"Quando un conducente deve usare particolare prudenza nei confronti di ciclisti e utenti vulnerabili?","options":["Solo quando è presente una pattuglia","Solo di notte","Sempre, adeguando velocità e distanza alle condizioni concrete","Soltanto nelle piste ciclabili"],"correct_index":2,"explanation":"Art. 141 e disposizioni di circolazione — prudenza e tutela degli utenti vulnerabili. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 141 e disposizioni di circolazione — prudenza e tutela degli utenti vulnerabili"},{"prompt":"Quando un veicolo adibito a servizi urgenti può usare i dispositivi supplementari previsti dall’art. 177?","options":["Per superare una coda senza emergenza","Per ottenere precedenza in ogni spostamento ordinario","Ogni volta che il conducente è in ritardo","Nei casi di servizio urgente previsti dalla norma, con i dispositivi prescritti"],"correct_index":3,"explanation":"Art. 177 CdS — veicoli di emergenza. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 177 CdS — veicoli di emergenza"},{"prompt":"Secondo l’art. 141, il conducente deve essere sempre in grado di:","options":["Superare rapidamente ogni ostacolo","Frenare soltanto con il freno di stazionamento","Conservare il controllo del veicolo e compiere le manovre necessarie in sicurezza","Mantenere la velocità del flusso anche con scarsa visibilità"],"correct_index":2,"explanation":"Art. 141 CdS — controllo del veicolo. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.normattiva.it/eli/id/1992/05/18/092G0306/CONSOLIDATED/20260924","source_note":"Art. 141 CdS — controllo del veicolo"}]$land$::jsonb)
 as q(prompt text, options jsonb, correct_index smallint, explanation text, source_url text, source_note text)
),
sea_questions as (
 select * from jsonb_to_recordset($sea$[{"prompt":"A quali acque si applicano in generale le COLREG?","options":["Alle acque alte e alle acque connesse navigabili da navi marittime secondo il campo di applicazione della convenzione","Solo alle acque territoriali di uno Stato aderente","A tutte le acque interne non navigabili","Solo ai porti commerciali"],"correct_index":0,"explanation":"COLREG Rule 1 — Application. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 1 — Application"},{"prompt":"Che cosa definisce la Rule 32?","options":["I colori dei fanali laterali","La velocità sicura","I termini relativi ai segnali sonori, tra cui fischio, suono breve e suono prolungato","La precedenza tra navi a vela"],"correct_index":2,"explanation":"COLREG Rule 32 — Definitions. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 32 — Definitions"},{"prompt":"Che cosa indica una sequenza di almeno cinque suoni brevi e rapidi?","options":["La nave è all’ancora","Dubbio o pericolo circa le intenzioni o le azioni dell’altra nave","La richiesta di rimorchio","La nave è in pesca"],"correct_index":1,"explanation":"COLREG Rule 34 — Doubt or danger signal. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 34 — Doubt or danger signal"},{"prompt":"Che cosa richiede la Rule 5 in materia di vedetta?","options":["Solo l’uso del radar","Una vedetta appropriata con vista, udito e tutti i mezzi disponibili adeguati","Una vedetta soltanto con visibilità ridotta","Solo l’ascolto delle comunicazioni radio"],"correct_index":1,"explanation":"COLREG Rule 5 — Look-out. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 5 — Look-out"},{"prompt":"Chi è responsabile dell’osservanza delle regole e delle precauzioni richieste dalla buona pratica marinaresca?","options":["Soltanto l’armatore","Solo l’autorità portuale","Soltanto il timoniere","Comandante, proprietario e equipaggio secondo le rispettive responsabilità"],"correct_index":3,"explanation":"COLREG Rule 2 — Responsibility. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 2 — Responsibility"},{"prompt":"Come deve essere valutato il rischio di collisione secondo la Rule 7?","options":["Usando tutti i mezzi disponibili e valutando correttamente le informazioni, incluso il radar se presente","Solo quando l’altra unità è a meno di un miglio","Solo in base alla distanza visiva","Soltanto dopo aver ricevuto una chiamata radio"],"correct_index":0,"explanation":"COLREG Rule 7 — Risk of collision. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 7 — Risk of collision"},{"prompt":"Come deve procedere un’unità rispetto alla velocità di sicurezza?","options":["Sempre alla massima velocità consentita dal motore","A velocità costante indipendentemente dalla visibilità","A velocità sicura in ogni momento, valutando le circostanze e condizioni prevalenti","Alla velocità media delle altre unità"],"correct_index":2,"explanation":"COLREG Rule 6 — Safe speed. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 6 — Safe speed"},{"prompt":"Due navi a propulsione meccanica si avvicinano su rotte opposte con rischio di collisione. Qual è la manovra prevista dalla Rule 14?","options":["Una arresta i motori e l’altra mantiene la rotta","Entrambe mantengono rotta e velocità","Entrambe accostano a sinistra","Entrambe accostano a dritta in modo da passare sinistra a sinistra"],"correct_index":3,"explanation":"COLREG Rule 14 — Head-on situation. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 14 — Head-on situation"},{"prompt":"In generale, rispetto a una nave a vela che naviga a vela, come deve comportarsi una nave a propulsione meccanica?","options":["Deve mantenere la rotta senza valutare le altre unità","Deve spegnere i motori","Ha sempre precedenza perché è più manovrabile","Deve tenersi discosta secondo la gerarchia della Rule 18"],"correct_index":3,"explanation":"COLREG Rule 18 — Responsibilities between vessels. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 18 — Responsibilities between vessels"},{"prompt":"In un canale stretto, quale regola generale deve seguire una nave che procede lungo il canale?","options":["Mantenersi sul lato sinistro","Mantenersi il più possibile vicino al limite esterno sul lato di dritta, se sicuro e praticabile","Navigare al centro in ogni circostanza","Attraversare il canale quando vuole"],"correct_index":1,"explanation":"COLREG Rule 9 — Narrow channels. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 9 — Narrow channels"},{"prompt":"In una situazione di incrocio tra due navi a propulsione meccanica, quale nave deve manovrare secondo la Rule 15?","options":["Quella più veloce","Quella che ha l’altra sulla propria dritta","Quella che vede l’altra a sinistra","Quella più grande"],"correct_index":1,"explanation":"COLREG Rule 15 — Crossing situation. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 15 — Crossing situation"},{"prompt":"In una situazione di sorpasso, quale unità deve tenersi discosta?","options":["L’unità che sorpassa","L’unità con velocità inferiore","L’unità raggiunta","L’unità più piccola in ogni caso"],"correct_index":0,"explanation":"COLREG Rule 13 — Overtaking. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 13 — Overtaking"},{"prompt":"In visibilità ristretta, quale condotta è richiesta?","options":["Affidarsi soltanto al GPS","Procedere a velocità di sicurezza e adottare le misure previste dalla Rule 19","Procedere alla massima velocità per uscire dalla nebbia","Spegnere il radar per evitare falsi echi"],"correct_index":1,"explanation":"COLREG Rule 19 — Conduct in restricted visibility. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 19 — Conduct in restricted visibility"},{"prompt":"Qual è il comportamento iniziale della nave che deve mantenere rotta e velocità?","options":["Deve mantenere rotta e velocità, restando pronta ad agire quando previsto dalla Rule 17","Deve spegnere i fanali","Deve sempre accostare immediatamente","Deve invertire la marcia"],"correct_index":0,"explanation":"COLREG Rule 17 — Action by stand-on vessel. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 17 — Action by stand-on vessel"},{"prompt":"Qual è il principio corretto nell’applicazione delle COLREG durante una situazione non espressamente risolta da una singola regola?","options":["Seguire soltanto la rotta GPS","Mantenere sempre la massima velocità","Ignorare le altre unità","Agire con prudenza, valutando circostanze, rischi e responsabilità secondo la Rule 2"],"correct_index":3,"explanation":"COLREG Rule 2 — Responsibility and ordinary practice of seamen. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 2 — Responsibility and ordinary practice of seamen"},{"prompt":"Qual è lo scopo principale degli schemi di separazione del traffico?","options":["Consentire sorpassi in ogni direzione","Riservare le corsie alle sole navi da pesca","Organizzare i flussi di traffico e ridurre il rischio di collisione","Sostituire tutte le altre regole COLREG"],"correct_index":2,"explanation":"COLREG Rule 10 — Traffic separation schemes. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 10 — Traffic separation schemes"},{"prompt":"Quale caratteristica deve avere un’azione intrapresa per evitare una collisione?","options":["Essere eseguita soltanto con il timone","Essere sempre una virata a sinistra","Essere minima e tardiva","Essere tempestiva, positiva e conforme alla buona pratica marinaresca"],"correct_index":3,"explanation":"COLREG Rule 8 — Action to avoid collision. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 8 — Action to avoid collision"},{"prompt":"Quale dotazione sonora è richiesta in generale alle navi di almeno 12 metri?","options":["Un fischio e una campana secondo la Rule 33","Un segnale luminoso giallo","Solo una campana","Un radar e un ecoscandaglio"],"correct_index":0,"explanation":"COLREG Rule 33 — Equipment for sound signals. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 33 — Equipment for sound signals"},{"prompt":"Quale fanale identifica il settore di dritta di una nave?","options":["Verde","Giallo","Rosso","Bianco"],"correct_index":0,"explanation":"COLREG Rule 21 — Definitions of lights. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 21 — Definitions of lights"},{"prompt":"Quale regola disciplina i fanali delle navi impegnate nella pesca?","options":["Rule 17","Rule 26","Rule 13","Rule 30"],"correct_index":1,"explanation":"COLREG Rule 26 — Fishing vessels. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 26 — Fishing vessels"},{"prompt":"Quale regola disciplina i fanali delle navi pilota?","options":["Rule 14","Rule 29","Rule 6","Rule 30"],"correct_index":1,"explanation":"COLREG Rule 29 — Pilot vessels. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 29 — Pilot vessels"},{"prompt":"Quale regola disciplina i fanali e i segnali di una nave all’ancora o incagliata?","options":["Rule 30","Rule 8","Rule 15","Rule 5"],"correct_index":0,"explanation":"COLREG Rule 30 — Anchored vessels and vessels aground. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 30 — Anchored vessels and vessels aground"},{"prompt":"Quale regola disciplina i segnali di soccorso e pericolo?","options":["Rule 37","Rule 23","Rule 8","Rule 17"],"correct_index":0,"explanation":"COLREG Rule 37 — Distress signals. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 37 — Distress signals"},{"prompt":"Quale regola disciplina i segnali sonori in condizioni di visibilità ristretta?","options":["Rule 10","Rule 22","Rule 35","Rule 13"],"correct_index":2,"explanation":"COLREG Rule 35 — Sound signals in restricted visibility. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 35 — Sound signals in restricted visibility"},{"prompt":"Quale regola disciplina le luci di una nave impegnata in operazioni di rimorchio?","options":["Rule 21","Rule 33","Rule 19","Rule 24"],"correct_index":3,"explanation":"COLREG Rule 24 — Towing and pushing. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 24 — Towing and pushing"},{"prompt":"Quale segnalazione luminosa riguarda una nave non governabile?","options":["I soli fanali di una nave a vela","Nessuna segnalazione specifica","I fanali e i segnali prescritti dalla Rule 27","I fanali di una nave all’ancora"],"correct_index":2,"explanation":"COLREG Rule 27 — Vessels not under command or restricted in ability to manoeuvre. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 27 — Vessels not under command or restricted in ability to manoeuvre"},{"prompt":"Quale significato ha un suono breve secondo i segnali di manovra della Rule 34?","options":["Sto dando fondo","Sono all’ancora","Accosto a sinistra","Sto accostando a dritta"],"correct_index":3,"explanation":"COLREG Rule 34 — Manoeuvring and warning signals. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 34 — Manoeuvring and warning signals"},{"prompt":"Quali fanali deve mostrare in generale una nave a propulsione meccanica in navigazione secondo la Rule 23?","options":["Solo un fanale bianco a poppa","Un fanale verde a 360 gradi","Solo un fanale rosso","I fanali prescritti per nave a propulsione meccanica, inclusi fanale di testa d’albero e fanali laterali, secondo dimensioni e configurazione"],"correct_index":3,"explanation":"COLREG Rule 23 — Power-driven vessels underway. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 23 — Power-driven vessels underway"},{"prompt":"Quando si applicano le regole relative ai fanali e ai segnali diurni?","options":["Solo durante la navigazione diurna","Soltanto quando si è in porto","In ogni condizione prevista dalla convenzione, con i fanali prescritti dal tramonto all’alba e in altre condizioni di visibilità ridotta","Solo alle navi commerciali"],"correct_index":2,"explanation":"COLREG Rule 20 — Application of lights and shapes. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 20 — Application of lights and shapes"},{"prompt":"Secondo la Rule 16, come deve agire la nave che deve tenersi discosta?","options":["Attendere fino all’ultimo momento","Limitarsi a suonare la sirena","Manovrare con anticipo e in modo deciso per lasciare libera la rotta all’altra","Cambiare rotta ripetutamente"],"correct_index":2,"explanation":"COLREG Rule 16 — Action by give-way vessel. La risposta va interpretata sul testo vigente della norma citata.","source_url":"https://www.imo.org/en/about/conventions/pages/colreg.aspx","source_note":"COLREG Rule 16 — Action by give-way vessel"}]$sea$::jsonb)
 as q(prompt text, options jsonb, correct_index smallint, explanation text, source_url text, source_note text)
),
targets(vehicle_id,domain) as (values
 ('cc-subaru-crosstrek','land'),('cc-iveco-50c17-op','land'),
 ('cc-defender-110','land'),('cc-jeep-wrangler','land'),
 ('gdf-classe-monti','sea'),('gdf-classe-di-bartolo','sea'),
 ('gdf-classe-bigliani-viii','sea'),('gdf-bso-139','sea')
)
insert into public.vehicle_brevetto_question_bank
(vehicle_id,prompt,options,correct_index,explanation,source_url,source_note,category,active)
select t.vehicle_id,q.prompt,q.options,q.correct_index,q.explanation,q.source_url,q.source_note,'regulations',true
from targets t
cross join lateral (
 select * from land_questions where t.domain='land'
 union all
 select * from sea_questions where t.domain='sea'
) q
where not exists (
 select 1 from public.vehicle_brevetto_question_bank existing
 where existing.vehicle_id=t.vehicle_id and existing.category='regulations'
 and lower(trim(existing.prompt))=lower(trim(q.prompt))
);
